using System;
namespace LocalRaidShared;
public static class RaidSpawnRules {
 public static readonly string[] Factions={"scav","usec","bear","boss","follower","cultist","blackDivision","raider","rogue","other"};
 public static string Name(string faction)=>faction switch {"scav"=>"Scav（含狙击手）","usec"=>"USEC","bear"=>"BEAR","boss"=>"BOSS","follower"=>"保镖","cultist"=>"邪教徒","blackDivision"=>"黑色军团","raider"=>"掠夺者","rogue"=>"游荡者",_=>"其他阵营"};
 public static string Faction(string? role){role??="";if(role.Contains("blackdiv",StringComparison.OrdinalIgnoreCase)||role.Contains("blackfox",StringComparison.OrdinalIgnoreCase)||role.StartsWith("bossWedge",StringComparison.OrdinalIgnoreCase)||role.StartsWith("followerWedge",StringComparison.OrdinalIgnoreCase))return "blackDivision";if(role.StartsWith("sectant",StringComparison.OrdinalIgnoreCase)||role.StartsWith("sectact",StringComparison.OrdinalIgnoreCase))return "cultist";if(role.Equals("pmcUSEC",StringComparison.OrdinalIgnoreCase))return "usec";if(role.Equals("pmcBEAR",StringComparison.OrdinalIgnoreCase))return "bear";if(role.Equals("pmcBot",StringComparison.OrdinalIgnoreCase))return "raider";if(role.StartsWith("exUsec",StringComparison.OrdinalIgnoreCase))return "rogue";if(role.Contains("boss",StringComparison.OrdinalIgnoreCase))return "boss";if(role.Contains("follower",StringComparison.OrdinalIgnoreCase)||role.Equals("tagillaHelperAgro",StringComparison.OrdinalIgnoreCase))return "follower";if(role.StartsWith("assault",StringComparison.OrdinalIgnoreCase)||role.Equals("marksman",StringComparison.OrdinalIgnoreCase)||role.Equals("cursedAssault",StringComparison.OrdinalIgnoreCase))return "scav";return "other";}
 public static double Chance(double original,double multiplier)=>original<=0||multiplier<=0?0:Math.Min(100,original*multiplier);
 public static int Count(int original,double multiplier)=>original<=0||multiplier<=0?0:(int)Math.Min(int.MaxValue,Math.Round(original*multiplier,MidpointRounding.AwayFromZero));
}
